  function renderBankDeep(ctx){
    const core=globalThis.GH_BANKING_CORE;if(!core)return '<div class="empty">تعذر تحميل Banking Core.</div>';core.ensure(ctx.state);core.reconcilePrudential(ctx.state);ctx.ensureBankCorporateClients?.();
    const bank=ctx.state.bank,branches=bank.branchNetwork||[],activeBranches=branches.filter(row=>row.servicesActive),daily=bank.dailyHistory?.[0],breakdown=daily?.revenueBreakdown||{},requested=typeof ctx.currentArg==='object'?ctx.currentArg?.tab:ctx.currentArg,allowed=['overview','revenue','branches','credit','control'],tab=allowed.includes(requested)?requested:'overview',products=Object.entries(core.PRODUCTS||{}),portfolios=bank.loanPortfolios||[],corporateFacilities=bank.corporateFacilities||[],clients=Object.values(bank.corporateClients||{}),perf=ctx.companyPerformance?.('bank',30)||{};
    const nav=tabs([['overview','لوحة البنك'],['revenue','الإيرادات'],['branches','الفروع والخدمات'],['credit','الائتمان'],['control','السيولة والمخاطر']],tab,'data-bank-tab'),serviceCatalog=['حسابات وودائع','تحويلات ومدفوعات','بطاقات','تمويل أفراد','تمويل شركات','تمويل مشاريع','تجارة دولية','إدارة نقد الشركات','صرف العملات','قبول التجار ونقاط البيع'];let content='';
    if(tab==='overview')content=`<article class="list-item"><div class="list-item-head"><div><h3>بنك المجموعة · لوحة أعمال</h3><p>الودائع التزام. الإيراد الحقيقي يظهر من الفائدة والرسوم والخدمات وعائد الخزينة ويدخل نفس إقفال البنك المالي.</p></div><span class="tag ${Number(bank.cet1)>=Number(bank.riskPolicy.minCet1)?'positive':'negative'}">CET1 ${Number(bank.cet1).toFixed(1)}%</span></div>${metrics([['إيراد اليوم',ctx.fmtMoney(daily?Number(daily.interestIncome||0)+Number(daily.securityIncome||0)+Number((daily.reportedFeeIncome??daily.feeIncome)||0):0),'positive'],['صافي اليوم',ctx.fmtMoney(daily?.netBankingIncome||0),Number(daily?.netBankingIncome||0)>=0?'positive':'negative'],['إيراد 30 يوم',ctx.fmtMoney(perf.grossRevenue||0)],['صافي 30 يوم',ctx.fmtMoney(perf.net||0),Number(perf.net||0)>=0?'positive':'negative']])}${metrics([['الفروع',branches.length],['الودائع',ctx.fmtMoney(bank.deposits)],['القروض',ctx.fmtMoney(bank.loans)],['العملاء',ctx.fmtNumber(Number(bank.retailCustomers||0)+Number(bank.businessCustomers||0))]])}<div class="action-row"><button class="primary-btn" data-bank-tab="revenue">تفصيل الإيرادات</button>${action('bank-world-directory','فتح فرع عالمي')}<button class="secondary-btn" data-open="companyManage" data-arg="bank:management">إدارة البنك</button></div></article>`;
    if(tab==='revenue')content=`<article class="list-item revenue-center"><div class="list-item-head"><div><h3>مركز إيرادات البنك</h3><p>تفصيل تشغيلي واضح؛ جميع الفئات التالية تتجمع مرة واحدة داخل دخل الرسوم أو صافي الفائدة.</p></div><span class="tag positive">${ctx.fmtMoney(daily?Number(daily.interestIncome||0)+Number(daily.securityIncome||0)+Number((daily.reportedFeeIncome??daily.feeIncome)||0):0)}</span></div>${metrics([['صافي دخل الفائدة',ctx.fmtMoney(Number(daily?.interestIncome||0)+Number(daily?.securityIncome||0))],['الحسابات',ctx.fmtMoney(breakdown.accounts||0)],['التحويلات والمدفوعات',ctx.fmtMoney(breakdown.payments||0)],['البطاقات',ctx.fmtMoney(breakdown.cards||0)]])}${metrics([['قبول التجار',ctx.fmtMoney(breakdown.merchant||0)],['إدارة النقد',ctx.fmtMoney(breakdown.cashManagement||0)],['صرف العملات',ctx.fmtMoney(breakdown.fx||0)],['التجارة الدولية',ctx.fmtMoney(breakdown.tradeFinance||0)]])}${metrics([['تمويل أفراد',ctx.fmtMoney(breakdown.retailFinance||0)],['تمويل شركات',ctx.fmtMoney(breakdown.businessFinance||0)],['تمويل مشاريع',ctx.fmtMoney(breakdown.projectFinance||0)],['دخل رسوم اليوم',ctx.fmtMoney((daily?.reportedFeeIncome??daily?.feeIncome)||0),'positive']])}</article>${branches.map(branch=>`<article class="list-item"><div class="list-item-head"><div><h3>${ctx.esc(branch.city)} · ${ctx.esc(branch.country)}</h3><p>قائمة دخل الفرع</p></div><span class="tag ${Number(branch.incomeStatement?.net||0)>=0?'positive':'negative'}">${ctx.fmtMoney(branch.incomeStatement?.net||0)}</span></div>${metrics([['فائدة',ctx.fmtMoney(branch.incomeStatement?.interestIncome||0)],['خدمات ورسوم',ctx.fmtMoney(branch.incomeStatement?.feeIncome||0)],['تكلفة/مخاطر',ctx.fmtMoney(Number(branch.incomeStatement?.interestExpense||0)+Number(branch.incomeStatement?.creditLossExpense||0)+Number(branch.incomeStatement?.opex||0))]])}</article>`).join('')||'<div class="empty">لا يوجد فرع ينتج إيرادًا بعد.</div>'}`;
    if(tab==='branches')content=`<article class="list-item"><div class="list-item-head"><div><h3>الفروع والخدمات</h3><p>الفرع الجديد يبدأ بالخدمات الأساسية فقط. أنت توسّع خدماته من نفس مسار set-branch-services؛ لا توجد وظيفة مكررة.</p></div><span class="tag positive">${branches.length} فرع</span></div><div class="action-row">${action('bank-world-directory','فتح فرع جديد')}</div></article>${branches.map(branch=>`<article class="list-item bank-branch-service-card"><div class="list-item-head"><div><h3>${ctx.esc(branch.city)} · ${ctx.esc(branch.country)}</h3><p>${ctx.esc(branch.serviceModel||'أساسي')} · ${ctx.fmtNumber(branch.retailCustomers)} أفراد · ${ctx.fmtNumber(branch.businessCustomers)} أعمال</p></div><span class="tag ${branch.servicesActive?'positive':''}">${branch.servicesActive?'نشط':'متوقف'}</span></div><div class="bank-service-grid">${serviceCatalog.map(service=>`<label><input type="checkbox" data-bank-service="${ctx.esc(branch.id)}" value="${ctx.esc(service)}" ${(branch.services||[]).includes(service)?'checked':''}><span>${ctx.esc(service)}</span></label>`).join('')}</div>${metrics([['ودائع',ctx.fmtMoney(branch.deposits)],['قروض',ctx.fmtMoney(branch.loans)],['إيراد خدمات اليوم',ctx.fmtMoney(branch.incomeStatement?.feeIncome||0)],['صافي الفرع',ctx.fmtMoney(branch.incomeStatement?.net||0),Number(branch.incomeStatement?.net||0)>=0?'positive':'negative']])}<div class="action-row">${action('bank-save-branch-services','حفظ خدمات الفرع',`data-branch="${ctx.esc(branch.id)}"`)}</div></article>`).join('')||'<div class="empty">لا يوجد فرع مملوك؛ افتح أول فرع من الدليل العالمي.</div>'}`;
    if(tab==='credit')content=`<article class="list-item"><h3>منح تمويل</h3><div class="company-transfer-form"><label>المنتج<select id="bankLoanProduct">${products.map(([id,p])=>`<option value="${id}">${ctx.esc(p.name)} · ${(core.loanRate(ctx.state,id,'A')*100).toFixed(2)}%</option>`).join('')}</select></label><label>الفرع<select id="bankLoanBranch">${activeBranches.map(row=>`<option value="${ctx.esc(row.id)}">${ctx.esc(row.city)} · ${ctx.esc(row.country)}</option>`).join('')}</select></label><label>المبلغ<input id="bankLoanAmount" type="number" min="1000000" step="1000000" value="50000000"></label><label>التصنيف<select id="bankLoanRisk"><option>AAA</option><option>AA</option><option selected>A</option><option>BBB</option><option>BB</option><option>B</option></select></label><label>قطاع المقترض<select id="bankLoanSector"><option value="air">طيران</option><option value="sea">بحري</option><option value="road">لوجستيات</option><option value="mobility">تنقل</option><option value="power">طاقة</option><option value="real-estate">عقار</option><option value="industrial">صناعي</option><option value="trade">تجارة</option><option value="services">خدمات</option></select></label><label>تغطية الضمان<input id="bankLoanCollateral" type="number" min="0" max="5" step="0.05" value="1.25"></label></div><div class="action-row">${action('bank-originate-loan','منح التمويل',activeBranches.length?'':'disabled data-disabled-reason="افتح فرعًا نشطًا أولًا."')}</div></article><article class="list-item"><h3>محافظ القروض</h3>${portfolios.slice(0,35).map(row=>`<div class="bank-client-row"><div><b>${ctx.esc(row.name)} · ${ctx.esc(row.region)}</b><small>${ctx.esc(row.riskGrade||'BBB')} · Stage ${Number(row.stage||1)}</small></div><div><span>${ctx.fmtMoney(row.outstanding)}</span><small>EL ${ctx.fmtMoney(row.expectedLoss||0)}</small></div></div>`).join('')||'<p class="section-mini">لا توجد قروض بعد.</p>'}</article><article class="list-item"><h3>شركات المجموعة</h3>${clients.map(client=>`<div class="bank-client-row"><div><b>${ctx.esc(client.name)}</b><small>${ctx.esc(client.rating)} · حد ${ctx.fmtMoney(client.creditLimit)}</small></div><div class="action-row">${action('bank-draw-facility','سحب $10M',`data-company="${client.company}"`,true)}${action('bank-issue-lc','اعتماد $5M',`data-company="${client.company}"`,true)}${action('bank-issue-guarantee','ضمان $5M',`data-company="${client.company}"`,true)}</div></div>`).join('')}</article>`;
    if(tab==='control')content=`<article class="list-item"><h3>السيولة والتسعير</h3>${metrics([['HQLA',ctx.fmtMoney(bank.hqla)],['LCR',`${Number(bank.lcr).toFixed(0)}%`],['NSFR',`${Number(bank.nsfr).toFixed(0)}%`],['تمويل جملة',ctx.fmtMoney(bank.wholesaleFunding)]])}<div class="company-transfer-form"><label>تسعير الودائع<select id="bankDepositStance">${Object.keys(core.DEPOSIT_STANCES).map(stance=>{const rates=core.depositRates(ctx.state,stance);return `<option value="${stance}"${bank.depositPricing.stance===stance?' selected':''}>${{competitive:'تنافسي',market:'بسعر السوق',conservative:'محافظ'}[stance]} · ادخار ${(rates.savings*100).toFixed(2)}% · لأجل ${(rates.term*100).toFixed(2)}%</option>`;}).join('')}</select></label></div><p class="section-mini">الأسعار تتبع سعر الفائدة الأساسي يوميًا. التنافسي يجذب ودائع أكثر بتكلفة أعلى.</p><div class="action-row">${action('bank-deposit-pricing','اعتماد التسعير')}</div></article><article class="list-item"><h3>الخزينة وALM</h3><div class="company-transfer-form"><label>استثمار HQLA<input id="bankLiquidityInvestment" type="number" min="1000000" step="1000000" value="20000000"></label><label>الأداة والأجل<select id="bankLiquidityKind">${Object.entries(core.LIQUIDITY).flatMap(([kind,row])=>row.terms.map(term=>`<option value="${kind}:${term}">${{sovereign:'سند سيادي','central-bank':'إيداع بنك مركزي','covered-bond':'سند مغطى'}[kind]} · ${term<365?`${term} يومًا`:`${term/365} ${term===365?'سنة':'سنوات'}`} · ${(core.liquidityYield(ctx.state,kind,term)*100).toFixed(2)}%</option>`)).join('')}</select></label><label>تمويل جملة<input id="bankWholesaleAmount" type="number" step="1000000" value="50000000"></label><label>الأجل والتكلفة<select id="bankWholesaleTerm">${core.FUNDING_TERMS.map(term=>`<option value="${term}">${term/365} ${term===365?'سنة':'سنوات'} · ${(core.wholesaleRate(ctx.state,term)*100).toFixed(2)}%</option>`).join('')}</select></label></div><div class="action-row">${action('bank-invest-liquidity','استثمار السيولة')}${action('bank-wholesale-funding','تمويل جملة', '',true)}</div></article><article class="list-item"><h3>المخاطر</h3><div class="company-transfer-form"><label>حد LDR %<input id="bankRiskLdr" type="number" value="${Number(bank.riskPolicy.maxLdr)}"></label><label>حد LCR %<input id="bankRiskLcr" type="number" value="${Number(bank.riskPolicy.minLcr)}"></label><label>حد CET1 %<input id="bankRiskCet1" type="number" step="0.1" value="${Number(bank.riskPolicy.minCet1)}"></label><label>تركيز القطاع %<input id="bankRiskConcentration" type="number" value="${Number(bank.riskPolicy.sectorConcentration)}"></label></div><div class="action-row">${action('bank-risk-policy','اعتماد حدود المخاطر')}</div></article>`;
    return `${hero(photos.bank,identityName(ctx.state,'bank'),'لوحة أعمال مصرفية واضحة: الإيرادات والفروع والائتمان والسيولة والإدارة.','GH BANK')}${nav}<div class="list sector-command-center">${content}</div>`;
  }
      function renderResearch(ctx){const projects=[['efficiency','كفاءة الأساطيل','يخفض الوقود حتى 8% واحتياطي الصيانة حتى 2.5%'],['automation','أتمتة العمليات','يخفض مسير رواتب طواقم الأصول الثابت حتى 5% عند الاكتمال'],['cleanEnergy','الطاقة النظيفة','يخفض تكلفة الوقود حتى 1.8%']];const researchPrograms=ctx.state.advanced.researchPrograms||{};return `${hero(photos.system,'البحث والتطوير','كل مرحلة تستغرق 30 يومًا وتكلفتها 0.05% من قيمة المجموعة، وترفع المشروع 25 نقطة عند اكتمالها. الأثر يتدرج مع كل مرحلة مكتملة.','R&D')}<div class="list">${projects.map(([id,name,copy])=>{const pct=Number(ctx.state.research[id])||0,meta=researchPrograms[id]||{},stage=pct>=100?'تشغيلي':pct>=75?'اعتماد وتشغيل تجريبي':pct>=50?'اختبار موسع':pct>=25?'نموذج أولي':'فكرة ودراسة';return `<article class="list-item"><div class="list-item-head"><div><h3>${name}</h3><p>${copy}</p></div><span class="tag ${pct>=100?'positive':''}">${stage} · ${pct}%</span></div><div class="progress-bar"><span style="width:${pct}%"></span></div>${metrics([['الإنفاق المتراكم',ctx.fmtMoney(meta.spent||0)],['المراحل المكتملة',meta.rounds||0],['المرحلة الجارية',meta.phase?`تكتمل يوم ${Number(meta.phase.endDay)+1}`:'لا يوجد']])}<div class="action-row"><button class="primary-btn fund-research" data-project="${id}" ${pct>=100?'disabled data-disabled-reason="اكتمل المشروع ودخل التشغيل."':meta.phase?'disabled data-disabled-reason="المرحلة الحالية لم تكتمل بعد."':''}>تمويل مرحلة · ${ctx.fmtMoney(globalThis.GH_GOVERNANCE_CORE?.researchPhaseCost?.(ctx.state)||25000000)}</button></div></article>`}).join('')}</div>`;}
  function renderESG(ctx){
    const e=ctx.state.esg,su=ctx.state.sustainability||{targetYear:2035,renewableShare:12,safShare:0,shorePower:0,electricRoadShare:0,circularity:42,waterScore:55,supplyChainScore:60,disclosure:68,carbonIntensity:100,programs:{}};
    // Build 359: the fleet's emission mix comes from the daily sustainability tick (governance-core); rendering reads only.
    const mix=su.fleetMix||{total:0,lowEmission:0},lowShare=mix.total?Math.round(mix.lowEmission/mix.total*100):0;
    const score=globalThis.GH_GOVERNANCE_CORE?.esgScore?.(ctx.state)??0,reputationBonus=Number(globalThis.GH_GOVERNANCE_CORE?.programEffects?.(ctx.state)?.reputation)||0;
    // Build 359: cost and paying company come from the programme catalogue (GH_GOVERNANCE_CORE.ESG_PROGRAMS); each line
    // names the number it moves at full maturity.
    const catalog=globalThis.GH_GOVERNANCE_CORE?.ESG_PROGRAMS||{};
    const programs=[
      ['fleet','تحديث الأسطول منخفض الانبعاثات','يخفض وقود الشاحنات حتى 8% مع نسبة الطريق الكهربائي'],
      ['saf','وقود طيران مستدام SAF','يخفض وقود الطيران حتى 6%'],
      ['shore','كهرباء الموانئ Shore Power','يخفض وقود السفن حتى 5%'],
      ['renewable','طاقة متجددة للمرافق','يخفض تكلفة تشغيل كل المنشآت اليومية حتى 15%'],
      ['circular','الاقتصاد الدائري والصيانة','يخفض احتياطي الصيانة 4% وفواتير إصلاح الحوادث 5%'],
      ['supply','سلسلة توريد مسؤولة','يخفض أسعار الأصول الجديدة 2% ومدة التسليم 10%'],
      ['water','المياه والتنوع الحيوي','يخفض مؤشر تجديد التأمين حتى 5 نقاط'],
      ['disclosure','الإفصاح والحوكمة المناخية','يخفض علاوة الفائدة على الديون حتى 0.25 نقطة']
    ].map(([id,name,copy])=>[id,name,catalog[id]?.company||'group',Number(catalog[id]?.cost)||0,copy]);
    return `${hero(photos.power,'الاستدامة والتحول المؤسسي','منظومة تشغيل ومال ومخاطر تشمل الأسطول والطاقة والمرافق وسلسلة التوريد والحوكمة، وليس مؤشر ESG واحدًا.','SUSTAINABILITY 2.0')}
      <div class="list"><article class="list-item"><div class="list-item-head"><div><h3>لوحة التحول حتى ${su.targetYear}</h3><p>يربط البرنامج الاستثمار بتكلفة التشغيل، جودة التمويل، المخاطر والسمعة.</p></div><span class="tag positive">${score}/100</span></div><p class="section-mini">كل 10 نقاط فوق 60 ترفع سمعة الشركات نقطة، والسمعة ترفع الطلب 0.3% لكل نقطة. الأثر الحالي: +${reputationBonus} سمعة.</p>${metrics([['أسطول A/B',`${lowShare}%`],['طريق منخفض الانبعاث',`${su.electricRoadShare}%`],['طاقة متجددة',`${su.renewableShare}%`]])}${metrics([['دائرية',`${su.circularity}%`],['سلسلة توريد',`${su.supplyChainScore}%`],['إفصاح',`${su.disclosure}%`]])}</article>
      <article class="list-item"><h3>ESG الأساسي</h3>${metrics([['بيئي',e.environment],['اجتماعي',e.social],['حوكمة',e.governance]])}<p>الدرجة الأساسية تبقى متوافقة مع ملفات الحفظ، لكن القرار التشغيلي أصبح مبنيًا على البرامج التفصيلية أدناه.</p></article>
      ${programs.map(([id,name,company,cost,copy])=>{const prog=su.programs?.[id],maturity=Math.max(0,Math.min(100,Number(prog?.maturity)||0)),stateLabel=!prog?'مقترح':prog.lapsed?`متوقف · ${Math.round(maturity)}%`:maturity>=100?'مستقر تشغيليًا':`${prog.status||'قيد التنفيذ'} · ${Math.round(maturity)}%`;return `<article class="list-item"><div class="list-item-head"><div><h3>${name}</h3><p>${copy}</p></div><span class="tag ${prog?'positive':''}">${stateLabel}</span></div>${prog?`<div class="progress-bar"><span style="width:${maturity}%"></span></div>${metrics([['النضج',`${Math.round(maturity)}%`],['الإنفاق',ctx.fmtMoney(prog.cost||cost)],['الصيانة السنوية',ctx.fmtMoney(Math.round((prog.cost||cost)*.1))],['التجديد',prog.lapsed?'متأخر':`يوم ${Number(prog.nextUpkeepDay||0)+1}`]])}`:''}<div class="action-row">${action('esg-program',prog?'معتمد':`اعتماد · ${ctx.fmtMoney(cost)}`,`data-program="${id}" ${prog?'disabled data-disabled-reason="البرنامج معتمد ويظهر تقدمه في نفس البطاقة."':''}`,!!prog)}</div></article>`}).join('')}</div>`;
  }

    function renderBusinessWorld(ctx,arg){
    const W=globalThis.GH_BUSINESS_WORLD;if(!W?.snapshot)return '<div class="empty">Business World Core غير متاح.</div>';
    const view=arg&&typeof arg==='object'?arg:{tab:arg||'overview'},tab=view.tab||'overview',snap=W.snapshot(ctx.state),opened=['group',...(ctx.state.openedCompanies||[])];
    const nav=tabs([['overview','نظرة عامة'],['customers','العملاء'],['opportunities','الفرص'],['sponsorships','الرعايات'],['competitors','المنافسون']],tab,'data-business-tab');
    const partyName=id=>{const p=W.resolveParty(ctx.state,id);return p?.legalName||p?.displayName||'جهة تجارية';};
    const companyName=type=>identityName(ctx.state,type);
    let body='';
    if(tab==='overview'){
      const recent=snap.events.slice(0,10);
      body=`<article class="list-item"><div class="list-item-head"><div><h3>شبكة العلاقات التجارية</h3><p>هوية واحدة لكل جهة خارجية تربط الفرصة والعقد والفاتورة والحوالة والخبر. القرارات التي تخص شركاتك لا تنفذ تلقائيًا.</p></div><span class="tag positive">EVENT-DRIVEN</span></div>${metrics([['جهات خارجية',snap.parties.length],['عملاء',snap.customers.length],['فرص مفتوحة',snap.openOpportunities],['عقود نشطة',snap.activeContracts]])}</article>
      ${sectionTitle('آخر الحركة التجارية','أحداث ناتجة من العقود والمدفوعات والرعايات والسوق الخارجي؛ لا توجد أخبار مولدة بلا أصل.')}
      ${recent.length?recent.map(e=>`<article class="list-item"><div class="list-item-head"><div><h3>${ctx.esc(e.title)}</h3><p>${ctx.esc(partyName(e.partyId))}${e.detail?` · ${ctx.esc(e.detail)}`:''}</p></div><span class="tag ${e.severity==='positive'?'positive':''}">يوم ${Number(e.day||0)+1}</span></div>${e.amount?metrics([['القيمة',ctx.fmtMoney(e.amount)],['الشركة',ctx.esc(companyName(e.company))],['المرجع',ctx.esc(e.reference)] ]):''}</article>`).join(''):'<div class="empty">لا توجد حركة تجارية مسجلة بعد.</div>'}`;
    }
    if(tab==='customers'){
      const rows=snap.customers.slice(0,40).map(p=>W.customerSnapshot(ctx.state,p.id)).filter(Boolean);
      body=rows.length?rows.map(x=>`<article class="list-item"><div class="list-item-head"><div><h3>${ctx.esc(x.party.legalName||x.party.displayName)}</h3><p>${ctx.esc(x.party.industry||'عميل تجاري')} · ${ctx.esc(x.party.country||'دولي')}</p></div><span class="tag ${x.outstanding>0?'':'positive'}">${x.contracts.filter(o=>o.status==='نشط').length} عقد نشط</span></div>${metrics([['إجمالي الفوترة',ctx.fmtMoney(x.totalBilled)],['المحصّل',ctx.fmtMoney(x.received)],['ذمم مفتوحة',ctx.fmtMoney(x.outstanding),x.outstanding>0?'negative':'positive'],['علاقات شركات',x.relationships.length]])}<p class="section-mini">آخر تفاعل: ${x.lastInteractionAt?ctx.formatDuration(Math.max(0,ctx.state.simSeconds-x.lastInteractionAt)):'لا يوجد سجل مالي بعد'} · الفرص/العقود: ${x.opportunities.length}</p></article>`).join(''):'<div class="empty">لا يوجد عملاء مسجلون بعد.</div>';
    }
    if(tab==='opportunities'){
      body=snap.opportunities.length?snap.opportunities.slice(0,60).map(o=>`<article class="list-item"><div class="list-item-head"><div><h3>${ctx.esc(o.title)}</h3><p>${ctx.esc(partyName(o.partyId))} · ${ctx.esc(o.region||'دولي')} · ${ctx.esc(companyName(o.company))}</p></div><span class="tag ${o.status==='نشط'?'positive':o.status==='خسر العرض'?'negative':''}">${ctx.esc(o.status)}</span></div>${metrics([['القيمة',ctx.fmtMoney(o.value)],['المدة',`${o.termMonths||0} شهر`],['SLA',ctx.esc(o.sla||'—')],['الدفع',ctx.esc(o.payment||'—')]])}<div class="action-row"><button class="secondary-btn" data-open="contracts">فتح مركز العقود</button></div></article>`).join(''):'<div class="empty">لا توجد فرص تجارية.</div>';
    }
    if(tab==='sponsorships'){
      body=snap.sponsorships.map(o=>{const eligible=o.sectors.filter(x=>opened.includes(x)),party=partyName(o.partyId),active=o.status==='نشط';return `<article class="list-item"><div class="list-item-head"><div><h3>${ctx.esc(party)}</h3><p>${ctx.esc(o.rights)} · حصرية الفئة: ${ctx.esc(o.exclusivity)}</p></div><span class="tag ${active?'positive':''}">${ctx.esc(o.status)}</span></div>${metrics([['قيمة العقد',ctx.fmtMoney(o.value)],['المدة',`${o.termDays} يوم`],['الفترات المفوترة',o.billedPeriods||0],['الشركة',active?ctx.esc(companyName(o.company)):'لم تعتمد']])}${o.status==='عرض متاح'?`<label class="section-mini">الكيان المستفيد<select id="businessSponsorCompany-${ctx.esc(o.id)}">${eligible.map(x=>`<option value="${ctx.esc(x)}">${ctx.esc(companyName(x))}</option>`).join('')}</select></label><div class="action-row">${action('business-accept-sponsorship','قبول الرعاية',`data-offer="${ctx.esc(o.id)}" ${eligible.length?'':'disabled data-disabled-reason="أسس إحدى الشركات المؤهلة للرعاية أولًا."'}`)}${action('business-reject-sponsorship','رفض العرض',`data-offer="${ctx.esc(o.id)}"`,true)}</div>`:active?`<p class="section-mini">الفوترة الدورية التالية: يوم ${Number(o.nextBillingDay||0)+1}. قبول الرعاية كان قرارًا يدويًا؛ التحصيل اللاحق تنفيذ عقد قائم فقط.</p>`:''}</article>`;}).join('');
    }
    if(tab==='competitors'){
      body=`<article class="list-item"><h3>السوق المنافس</h3><p>المنافسون موجودون كجهات سوقية وتجارية، وليس مطلوبًا تمثيل أساطيلهم على الخريطة. نشاطهم الخارجي لا ينفذ أي إجراء داخل شركاتك.</p></article>${snap.competitors.slice(0,40).map(p=>`<article class="list-item"><div class="list-item-head"><div><h3>${ctx.esc(p.displayName||p.legalName)}</h3><p>${ctx.esc(p.industry||'شركة منافسة')} · ${ctx.esc(p.city||p.country||'دولي')}</p></div><span class="tag">${ctx.esc(p.marketShare||'—')}</span></div>${metrics([['القطاعات',(p.sectors||[]).map(ctx.typeName).join(' · ')||'متنوع'],['الاستراتيجية',ctx.esc(p.strategy||'—')]])}</article>`).join('')}${sectionTitle('نشاط المنافسين الأخير','أحداث أسبوعية خفيفة مرتبطة بالسوق فقط.')}${snap.competitorActivity.slice(0,15).map(e=>`<div class="spec-row"><span>يوم ${Number(e.day||0)+1} · ${ctx.esc(partyName(e.partyId))}</span><b>${ctx.esc(e.kind)}</b></div>`).join('')||'<div class="empty">لا توجد أحداث منافسين بعد.</div>'}`;
    }
    return `${hero(photos.hq,'العالم التجاري','شبكة موحدة للعملاء والمشترين والرعاة والمعلنين والمنافسين، مرتبطة بالعقد والمال والخبر دون قرارات آلية عنك.','BUSINESS WORLD')}${nav}<div class="list business-world-center">${body}</div>`;
  }

  // Build 359: the event cards are one function, used by the newsroom and by the action center (which used to cut the
  // newsroom's markup with a pattern that never matched, so it embedded the whole page with its hero).
  function newsEntries(ctx){
    const W=globalThis.GH_BUSINESS_WORLD,business=(W?.snapshot?.(ctx.state)?.events||[]).map(e=>({at:e.at,type:'business',category:'business',text:e.title,detail:e.detail,partyId:e.partyId,amount:e.amount,company:e.company,severity:e.severity,reference:e.reference})),internal=(ctx.state.eventLog||[]).slice(0,120);
    return [...business,...internal].sort((a,b)=>(Number(b.at)||0)-(Number(a.at)||0)).slice(0,160);
  }
  function newsClass(e){const t=String(e.type||'operation'),text=String(e.text||'');if(e.category==='business'||t==='business')return 'business';if(t==='economy'||/سوق|فائدة|وقود|طاقة|شحن|سعر/.test(text))return 'economy';if(t==='program'||/برنامج|مشروع|بحث/.test(text))return 'strategy';if(/فاتورة|ضريبة|سيولة|دين|شيك|تحويل/.test(text))return 'finance';return 'operations';}
  function newsSeverity(e){return e.severity&&e.severity!=='neutral'?e.severity:/خسار|مرتجع|تعذر|فشل|انخفاض|مخاطر|ضغط/.test(e.text||'')?'critical':/ارتفاع|افتتاح|اكتمل|اعتمد|نمو|توقيع|فوز/.test(e.text||'')?'positive':'neutral';}
