  function applyUpdateOperations(pack,ctx,sourceName){
    const id=pack.manifest.id||sourceName||`native-${pack.manifest.version}`;
    const duplicate=ctx.state.advanced.updateHistory.some(item=>item.id===id&&item.version===pack.manifest.version);
    if(duplicate)return false;
    const tx=globalThis.GH_TRANSACTION_CORE;if(!tx?.execute)throw new Error('Transaction Core unavailable for update operations');
    const backupKey=null,allowedOps=new Set(['content-config','balance-config','economy-config','add-events','visual-manifest']),stateSnapshot=tx.deepClone(ctx.state);
    const result=tx.execute(ctx.state,{label:`update-operations:${pack.manifest.version}`,apply:()=>{
      const ops=pack.__validatedOperations||[];for(const op of ops)if(!op||!allowedOps.has(op.type))throw new Error(`Unsupported update operation: ${String(op?.type||'empty')}`);
      const strategy=globalThis.GH_STRATEGY_CORE;if(!strategy?.execute)throw new Error('Strategy Core unavailable for runtime update state');
      strategy.execute({state:ctx.state},'apply-runtime-update',{id,version:pack.manifest.version,operations:ops,backupKey,rollbackOwner:'native-save-vault'});
      return true;
    }});
    if(!result?.committed)throw new Error(result?.reason||'Update operations transaction rejected');
    try{if(ctx.persistNow&&!ctx.persistNow({throwOnError:true}))throw new Error('Durable save failed after update operations');}
    catch(error){try{tx.restoreObject(ctx.state,stateSnapshot);}catch(restoreError){error.rollbackError=restoreError;}throw error;}
    ctx.pushAlert(`اكتمل تثبيت حزمة التحديث ${pack.manifest.version}. طُبقت عمليات الحالة ذريًا وحُفظت قبل إغلاق Pending Update.`);ctx.updateKpis();
    return true;
  }

  async function importUpdate(file,ctx){
    const status=document.getElementById('updateStatus');
    try{
      if(!inspectUpdateFile(file).ok)throw new Error('حجم ملف التحديث غير صالح أو يتجاوز 40MiB.');
      const pack=JSON.parse(await file.text());await validateUpdatePack(pack,{currentBuild:ctx.runtimeBuild});const nativeBridge=window.webkit?.messageHandlers?.updateBridge;
      if(!nativeBridge)throw new Error('التحديثات الموقعة تتطلب تطبيق iPhone للتحقق من توقيع Ed25519. لا يسمح بتطبيق حزمة دون التحقق Native.');
      const pendingKey=`global-holdings-pending-update`;const stagedPack={format:pack.format,manifest:pack.manifest,operationsJSON:pack.operationsJSON};localStorage.setItem(pendingKey,JSON.stringify({pack:stagedPack,sourceName:file.name,createdAt:Date.now()}));
      if(status)status.textContent='تم التحقق من البصمات. جاري التحقق Native من التوقيع والتثبيت الذري…';
      nativeBridge.postMessage({action:'installWebPack',manifest:pack.manifest,files:Array.isArray(pack.files)?pack.files:[],operationsJSON:pack.operationsJSON,saveJSON:JSON.stringify(ctx.state)});
    }catch(error){if(status)status.textContent=`فشل التحديث: ${error.message}`;}
  }

  window.addEventListener?.('gh-native-update',event=>{
    const status=document.getElementById('updateStatus'),ok=event.detail?.success===true||event.detail?.status==='success'||event.detail?.status==='installed';
    // Native owns the complete update lifecycle. This event is presentation-only;
    // re-applying operations here would create a second update owner.
    localStorage.removeItem('global-holdings-pending-update');
    if(status)status.textContent=event.detail?.message||(ok?'اكتملت عملية التحديث واعتمدها Native.':'فشل التحديث ولم تُعتمد الحزمة.');
  });

  let lastBoundContext=null;
  function bind(rootNode,ctx){lastBoundContext=ctx;
    rootNode.querySelectorAll('[data-gh-action]').forEach(btn=>{const id=String(btn.dataset.ghAction||''),valid=String(btn.tagName||'').toUpperCase()==='BUTTON'&&btn.dataset.ghActionOrigin===ACTION_ORIGIN&&ACTION_IDS.has(id);if(!valid){btn.removeAttribute?.('data-gh-action');btn.removeAttribute?.('data-gh-action-origin');btn.disabled=true;return;}if(btn.dataset.interactionBound==='1')return;btn.dataset.interactionBound='1';btn.addEventListener('click',()=>{const runner=globalThis.GH_INTERACTION?.run;return runner?runner(btn,()=>handleAction(btn,ctx),{action:btn.dataset.ghAction,state:ctx.state,panel:ctx.currentPanel}):handleAction(btn,ctx);});});
    rootNode.querySelectorAll('[data-facility-tab]').forEach(btn=>btn.addEventListener('click',()=>ctx.openDrawer('facilityManage',{id:ctx.currentArg?.id||ctx.currentArg,tab:btn.dataset.facilityTab})));
    rootNode.querySelectorAll('[data-company-manage-tab]').forEach(btn=>btn.addEventListener('click',()=>ctx.openDrawer('companyManage',{type:ctx.currentArg?.type||String(ctx.currentArg||'').split(':')[0],tab:btn.dataset.companyManageTab})));
    rootNode.querySelectorAll('[data-energy-tab]').forEach(btn=>btn.addEventListener('click',()=>ctx.openDrawer('energy',{tab:btn.dataset.energyTab})));
    rootNode.querySelectorAll('[data-bank-tab]').forEach(btn=>btn.addEventListener('click',()=>ctx.openDrawer('bank',{tab:btn.dataset.bankTab})));
    rootNode.querySelectorAll('[data-treasury-tab]').forEach(btn=>btn.addEventListener('click',()=>ctx.openDrawer('treasury',{tab:btn.dataset.treasuryTab})));
    rootNode.querySelectorAll('[data-news-filter]').forEach(btn=>btn.addEventListener('click',()=>ctx.openDrawer('news',{filter:btn.dataset.newsFilter})));
    rootNode.querySelectorAll('[data-business-tab]').forEach(btn=>btn.addEventListener('click',()=>ctx.openDrawer('businessWorld',{tab:btn.dataset.businessTab})));
    const input=rootNode.querySelector('#updateFileInput');if(input)input.addEventListener('change',()=>importUpdate(input.files?.[0],ctx));
    // Business artwork owns its own sector-aware recovery. Leaflet also renders
    // basemap tiles as <img>; enrolling those images here used to turn every
    // failed/offline tile into a headquarters photograph.
    rootNode.querySelectorAll('img[data-gh-image],.asset-thumb img,.asset-hero img,.thumb-sm img,.asset-marker img').forEach(img=>{
      if(img.classList.contains('leaflet-tile')||img.closest('.leaflet-tile-pane'))return;
      if(img.dataset.ghImageBound)return;img.dataset.ghImageBound='1';
      const originalSrc=img.getAttribute('src')||'';
      const fail=()=>{
        if(img.dataset.fallbackApplied)return;img.dataset.fallbackApplied='1';
        const src=originalSrc;
        img.src=/ship|port/.test(src)?photos.port:/air|airport/.test(src)?photos.airport:/truck|logistics/.test(src)?photos.logistics:photos.hq;
        img.closest('.asset-thumb,.asset-hero,.visual-hero,.company-visual-card')?.classList.add('image-recovered');
      };
      // Only the genuine 'error' event (network/404/decode failure) counts as a real failure.
      img.addEventListener('error',fail);
      // A 'load' that still reports zero natural size is a corrupt/empty file — also a real failure.
      img.addEventListener('load',()=>{if(img.naturalWidth===0)fail();});
      // If the browser reports the image already complete (e.g. cached) on bind, wait one frame before
      // trusting naturalWidth===0 as a failure signal — a not-yet-started `loading="lazy"` image can
      // legitimately report complete=true with naturalWidth=0 for a moment, which previously caused
      // every image to be swapped for a generic fallback the instant a panel rendered.
      if(img.complete){requestAnimationFrame(()=>{if(img.naturalWidth===0)fail();});}
    });
  }

  function onFinancialDay(state,processedDay=null){
    if(!state.advanced)return 0;
    const day=Number.isFinite(Number(processedDay))?Math.floor(Number(processedDay)):Math.floor((state.simSeconds||0)/86400);
    // All scheduled business maturities are advanced by their owning domain through the command plane.
    globalThis.GH_DOMAIN_COMMANDS?.dispatchSystem?.({state},'strategy','tick-day',{day},{actor:'simulation-scheduler'});
    globalThis.GH_DOMAIN_COMMANDS?.dispatchSystem?.({state},'hr','tick-day',{day},{actor:'simulation-scheduler'});
    // Only instantiated, operational companies receive a daily operations tick.
    // The registered operations provider owns the hook and its command domain;
    // catalog definitions must never create a financial book just to close a day.
    const platform=globalThis.GH_COMPANY_PLATFORM,adapters=globalThis.GH_COMPANY_ADAPTERS;
    if(!platform?.listInstances||!adapters?.resolveAdapter||!adapters?.invokeAdapter)throw new Error('company-daily-scheduler-owner-unavailable');
    const dailyOwners=[];
    for(const company of platform.listInstances(state,{openedOnly:true,includeGroup:false})){
      if(!company.operational)continue;
      const binding=adapters.resolveAdapter(state,company.id,'operations',{operational:true});
      const owner=Object.values(binding.engines).find(engine=>typeof engine.onFinancialDay==='function');
      if(!owner)continue;
      const order=owner.DAILY_FINANCIAL_ORDER??1000;
      if(!Number.isSafeInteger(order)||order<0)throw new Error('company-daily-order-invalid');
      dailyOwners.push({companyId:company.id,order,index:dailyOwners.length});
    }
    // Ordering belongs to the providers, not company IDs or presentation order.
    // Preserve existing cross-domain cash/debt precedence within the same close.
    dailyOwners.sort((a,b)=>a.order-b.order||a.index-b.index);
    for(const owner of dailyOwners){
      const result=adapters.invokeAdapter(state,owner.companyId,'operations','onFinancialDay',[{day}],{operational:true});
      if(result&&typeof result.then==='function')throw new Error('asynchronous-company-day-forbidden');
    }
    globalThis.GH_DOMAIN_COMMANDS?.dispatchSystem?.({state},'business-world','tick-day',{day},{actor:'simulation-scheduler'});
    const conferenceTick=globalThis.GH_DOMAIN_COMMANDS?.dispatchSystem?.({state},'conference','tick-day',{day},{actor:'simulation-scheduler'})?.result;
    if(conferenceTick?.prepared)globalThis.GH_DOMAIN_COMMANDS?.dispatchSystem?.({state},'operations','record-alert',{id:`CONF-READY-${conferenceTick.pendingYear}`,type:'annual-conference',text:`التقرير السنوي ${conferenceTick.pendingYear} جاهز. افتح المؤتمر التنفيذي من مركز إدارة المجموعة لتجهيز الحدث.`},{actor:'simulation-scheduler'});
    // Facility P&L is booked by the owning subsidiary in app.js. This hook returns the parent-only compliance overhead.
    return (state.advanced.cyber.coverage+state.advanced.safety.score<150)?12000:4500;
  }

  function adjustTripEconomics(state,asset,eco){
    const owner=assetOwnerCompanyId(asset),mode=assetMode(asset),company=companyModel(state,owner),research=state.research||{};if(!owner||!company)throw new Error('asset-company-model-unavailable');
    const serviceRevenue=1+Math.max(-.05,Math.min(.08,(company.serviceLevel-85)*.002));
    const fuelEfficiency=1-Math.min(.12,(research.efficiency||0)/100*.08+company.automation/100*.025);
    const crewEfficiency=1-Math.min(.10,(research.automation||0)/100*.05+company.automation/100*.035);
    const maintenanceEfficiency=1-Math.min(.08,company.automation/100*.04+(research.efficiency||0)/100*.025),su=state.sustainability||{},sustainabilityFuel=mode==='air'?1-Math.min(.06,(su.safShare||0)*.0004):mode==='sea'?1-Math.min(.05,(su.shorePower||0)*.00025):1-Math.min(.08,(su.electricRoadShare||0)*.00045);
    const wear=Math.max(0,Math.min(.45,Number(globalThis.GH_REALISM?.fleetWear?.(state,owner))||0)),flown=1-Math.max(0,Math.min(.5,Number(globalThis.GH_REALISM?.crewShortage?.(state,owner))||0)),skillRead=globalThis.GH_HR_CORE?.managerSkill?.(state,owner),skill=Math.max(0,Math.min(100,Number(skillRead)||0)),managed=skillRead===undefined?1:skill>0?1+(skill-80)*.002:.97;
    eco.revenue*=serviceRevenue*(1-wear*.15)*flown*managed;eco.fuelCost*=fuelEfficiency*sustainabilityFuel*(1+wear*.2)*flown*(mode==='sea'?Number(globalThis.GH_GOVERNANCE_CORE?.seaFuelFactor?.(state)??1):1);eco.crewCost*=crewEfficiency;eco.maintReserve*=maintenanceEfficiency*(Number(globalThis.GH_GOVERNANCE_CORE?.programEffects?.(state)?.maintenance)||1)*flown;eco.fees=(Number(eco.fees)||0)*flown;
    eco.margin=eco.revenue-eco.fuelCost-eco.crewCost-eco.maintReserve-(Number(eco.fees)||0);
    eco.cashContribution=eco.revenue-eco.fuelCost-eco.maintReserve-(Number(eco.fees)||0);
    eco.modifiers={serviceRevenue,fuelEfficiency,crewEfficiency,maintenanceEfficiency};
    return eco;
  }


  function onMarketHour(state,processedHour=null){
    const m=state.advanced.economy;
    if(window.GH_REALISM?.migrate){const re=window.GH_REALISM.migrate(state).economy;globalThis.GH_DOMAIN_COMMANDS?.dispatchSystem?.({state},'market','sync-economy',{values:{electricityPriceMWh:re.electricity,gasCostMWh:re.gas,freightIndex:re.freight,baseRate:re.baseRate,loanYield:Math.max((Number(m.depositRate)||0)+.012,re.baseRate+.028)}},{actor:'simulation-market'});return;}
    const move=(scale)=>((globalThis.GH_DETERMINISM?.nextFloat?.(state,'advanced-market')??0.5)-.5)*scale;
    const marketResult=globalThis.GH_DOMAIN_COMMANDS?.dispatchSystem?.({state},'market','tick-economy',{move},{actor:'simulation-market'})?.result||m;
    const hour=Number.isFinite(Number(processedHour))?Math.floor(Number(processedHour)):Math.floor((state.simSeconds||0)/3600);if(hour&&hour%12===0&&state.advanced.economy.lastNewsHour!==hour){const headline=marketResult.freightIndex>125?'ارتفاع مؤشر الشحن رفع تسعير العقود البحرية والجوية.':marketResult.gasCostMWh>75?'ارتفاع الطاقة والوقود يستدعي مراجعة هوامش المسارات.':marketResult.electricityPriceMWh>105?'ارتفاع أسعار الكهرباء يعزز ربحية أصول الطاقة.':'استقرار نسبي في الشحن والطاقة مع مراقبة أسعار الفائدة.';globalThis.GH_DOMAIN_COMMANDS?.dispatchSystem?.({state},'strategy','economy-news',{hour,text:headline},{actor:'simulation-market'});}
  }

  window.GH_ADVANCED={VERSION,LABOR_TABS,SAVE_SCHEMA_VERSION,UPDATE_LIMITS,photos,migrate,meta,root,render,bind,actionAttributes,sanitizeMarkup,signedDomainCommand,onFinancialDay,adjustTripEconomics,onMarketHour,photoFor,inspectUpdateFile,validateUpdatePack,applyNativeUpdate:async(pack,ctx)=>{await validateUpdatePack(pack,{currentBuild:ctx.runtimeBuild,postInstall:true});return applyUpdateOperations(pack,ctx,'التحديث الأصلي');}};
